const Redis = require('ioredis');

(async () => {
  const redis = new Redis();
  await redis.mset('user:1','Ada','user:2','Linus','session:1','active');

  let cursor = '0';
  do {
    const result = await redis.scan(cursor, 'MATCH', 'user:*', 'COUNT', 100);
    cursor = result[0];
    for (const key of result[1]) console.log(key);
  } while (cursor !== '0');

  await redis.quit();
})();

